CREATE TABLE "c_Activity" ("id" BIGINT NOT NULL, "a_Activity_activity_type" TEXT NOT NULL, "a_Activity_occurred_at" TIMESTAMP NOT NULL, "r_ContactActivities_source_id" BIGINT, "r_ContactActivities_source_dtype" TEXT, PRIMARY KEY ("id"), CHECK ("r_ContactActivities_source_dtype" IS NULL OR "r_ContactActivities_source_dtype" IN ('Contact','CustomerContact','Lead')), CHECK ((TRUE) OR "r_ContactActivities_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_ContactActivities_source_id" IS NOT NULL));
CREATE TABLE "c_Contact" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Contact_email" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Contact','CustomerContact','Lead')));
CREATE TABLE "c_CustomerContact" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_CustomerContact_customer_since" DATE NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('CustomerContact')));
CREATE TABLE "c_Lead" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Lead_source" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Lead')));
CREATE TABLE "c_Opportunity" ("id" BIGINT NOT NULL, "a_Opportunity_amount" NUMERIC NOT NULL, "a_Opportunity_stage" TEXT NOT NULL, "r_ContactOpportunities_source_id" BIGINT, "r_ContactOpportunities_source_dtype" TEXT, PRIMARY KEY ("id"), CHECK ("r_ContactOpportunities_source_dtype" IS NULL OR "r_ContactOpportunities_source_dtype" IN ('Contact','CustomerContact','Lead')), CHECK ((TRUE) OR "r_ContactOpportunities_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_ContactOpportunities_source_id" IS NOT NULL));
CREATE TABLE "c_Organization" ("id" BIGINT NOT NULL, "a_Organization_name" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "l_OrgContacts" ("r_OrgContacts_source_id" BIGINT NOT NULL, "r_OrgContacts_target_id" BIGINT NOT NULL, "r_OrgContacts_target_dtype" TEXT NOT NULL, PRIMARY KEY ("r_OrgContacts_source_id", "r_OrgContacts_target_id"), UNIQUE ("r_OrgContacts_target_id"), CHECK ("r_OrgContacts_target_dtype" IS NULL OR "r_OrgContacts_target_dtype" IN ('Contact','CustomerContact','Lead')));
ALTER TABLE "c_Activity" ADD CONSTRAINT "fk_c_Activity_0" FOREIGN KEY ("r_ContactActivities_source_id", "r_ContactActivities_source_dtype") REFERENCES "c_Contact" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_CustomerContact" ADD CONSTRAINT "fk_c_CustomerContact_0" FOREIGN KEY ("id", "dtype") REFERENCES "c_Contact" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_Lead" ADD CONSTRAINT "fk_c_Lead_0" FOREIGN KEY ("id", "dtype") REFERENCES "c_Contact" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_Opportunity" ADD CONSTRAINT "fk_c_Opportunity_0" FOREIGN KEY ("r_ContactOpportunities_source_id", "r_ContactOpportunities_source_dtype") REFERENCES "c_Contact" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_OrgContacts" ADD CONSTRAINT "fk_l_OrgContacts_0" FOREIGN KEY ("r_OrgContacts_source_id") REFERENCES "c_Organization" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_OrgContacts" ADD CONSTRAINT "fk_l_OrgContacts_1" FOREIGN KEY ("r_OrgContacts_target_id", "r_OrgContacts_target_dtype") REFERENCES "c_Contact" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION "require_OrgContacts"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Contact" t WHERE (t.dtype IN ('Contact','CustomerContact','Lead')) AND NOT EXISTS (SELECT 1 FROM "l_OrgContacts" l WHERE l."r_OrgContacts_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: OrgContacts'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_OrgContacts_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Contact" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_OrgContacts"();
CREATE CONSTRAINT TRIGGER "ct_OrgContacts_link" AFTER INSERT OR UPDATE OR DELETE ON "l_OrgContacts" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_OrgContacts"();